    public static Strings Get(Language l) => All.TryGetValue(l, out var s) ? s : All[Language.EN];

    public static Language Parse(string code) => code switch {
        "PL" => Language.PL, "DE" => Language.DE, "FR" => Language.FR,
        "ES" => Language.ES, "IT" => Language.IT, "CZ" => Language.CZ,
        "RU" => Language.RU, "ZH" => Language.ZH, _ => Language.EN,
    };

    public static string Code(Language l) => l switch {
        Language.PL => "PL", Language.DE => "DE", Language.FR => "FR",
        Language.ES => "ES", Language.IT => "IT", Language.CZ => "CZ",
        Language.RU => "RU", Language.ZH => "ZH", _ => "EN",
    };

    public static string FlagEmoji(Language l) => l switch {
        Language.PL => "🇵🇱", Language.DE => "🇩🇪", Language.FR => "🇫🇷",
        Language.ES => "🇪🇸", Language.IT => "🇮🇹", Language.CZ => "🇨🇿",
        Language.RU => "🇷🇺", Language.ZH => "🇨🇳", _ => "🇬🇧",
    };
